<script setup lang="ts">
import {localFetch,readJson} from './http'
import {computed,onMounted,onUnmounted,ref,watch} from 'vue'
import Icon from './Icon.vue'
type Part={text:string;url?:string}
type Risk={score?:number|null;coverage?:number|null;target_equity_pct?:number|null;current_equity_pct?:number|null;status?:string;factors?:{name:string;score:number|null;available:boolean}[]}
type Evidence={date:string;captured_at:string;news_cutoff:string;dates:Record<string,string|null>;warnings:string[];coverage?:Record<string,unknown>;sector_inflow?:{name:string;inst_value:number}[];sector_outflow?:{name:string;inst_value:number}[];strategies?:{date?:string|null;risk?:Risk|null};execution?:{target_date?:string|null;contract?:string|null};method:string}
type Futures={resistance1?:number|null;resistance2?:number|null;open?:number|null;close?:number|null;support1?:number|null;support2?:number|null;contract?:string|null;reason?:string}
type Saved={id:string;date:string;status:string;created_at:string;model:string;error:string;context:Evidence|null;result:{parts:Part[];sources:{title:string;url:string}[];usage:{input_tokens?:number;output_tokens?:number};request_meta?:{version:string;scope?:string;input_chars:number;topic_count?:number;candidate_count?:number};tracking?:{futures?:Futures};model?:string}|null}
type State={config:{configured:boolean;model:string;source:string};history:Saved[];selected:Saved|null;running:Saved|null;dates:string[]}
const state=ref<State|null>(null),preview=ref<Evidence|null>(null),date=ref(''),selectedId=ref(''),error=ref(''),notice=ref(''),loading=ref(false),starting=ref(false),saving=ref(false),apiKey=ref(''),model=ref('chat-latest'),editing=ref(false)
let timer:ReturnType<typeof setTimeout>|undefined,alive=true,epoch=0,previewEpoch=0
const running=computed(()=>starting.value||!!state.value?.running)
const savedForDate=computed(()=>state.value?.history.find(r=>r.date===date.value&&r.status==='complete'))
const active=computed(()=>state.value?.selected)
const evidence=computed(()=>active.value?.status==='complete'?active.value.context:preview.value)
const allocation=computed(()=>evidence.value?.strategies?.risk)
const forecast=computed(()=>active.value?.result?.tracking?.futures)
const fmt=(n:number|null|undefined,d=0)=>n==null?'—':n.toLocaleString('zh-TW',{maximumFractionDigits:d})
const stamp=(s:string)=>s.replace('T',' ').slice(0,16)
const labels:Record<string,string>={broker:'券商資料',rs:'RS 排行',sector:'族群流向',dictionary:'族群字典'}
function link(url:string|undefined){try{const u=new URL(url||'');return ['https:','http:'].includes(u.protocol)&&!u.username&&!u.password?u.href:undefined}catch{return undefined}}
const blocks=computed(()=>{
 const rows:Part[][]=[[]]
 for(const part of active.value?.result?.parts||[]){const lines=part.text.split('\n');lines.forEach((text,i)=>{if(i)rows.push([]);rows[rows.length-1].push({text,url:link(part.url)})})}
 return rows.filter(parts=>parts.some(p=>p.text.trim())).map(parts=>{const first=parts[0]?.text||'';const heading=/^#{1,3}\s/.test(first);return {heading,parts:parts.map((p,i)=>({...p,text:(i===0?p.text.replace(/^#{1,3}\s+/,''):p.text).replaceAll('**','')}))}})
})
async function json(url:string,options?:RequestInit){const r=await localFetch(url,options),data=await readJson(r);if(!r.ok)throw new Error(data.error||'讀取失敗');return data}
async function load(){
 const token=++epoch;clearTimeout(timer);loading.value=true
 try{const q=new URLSearchParams();if(selectedId.value)q.set('id',selectedId.value);else if(date.value)q.set('date',date.value)
  const data:State=await json('/api/research?'+q);if(!alive||token!==epoch)return
  state.value=data;if(!editing.value)model.value=data.config.model
  if(!date.value&&data.dates.length)date.value=data.dates[0]
  if(data.running)timer=setTimeout(load,2500)
 }catch(e){if(alive&&token===epoch)error.value=String(e)}finally{if(alive&&token===epoch)loading.value=false}
}
async function loadPreview(){const token=++previewEpoch;preview.value=null;if(!date.value)return
 try{const data=await json('/api/research/context?date='+encodeURIComponent(date.value));if(alive&&token===previewEpoch)preview.value=data}catch(e){if(alive&&token===previewEpoch)error.value=String(e)}
}
async function generate(force=false){starting.value=true;error.value='';notice.value=''
 try{const latest=!state.value?.dates.length||date.value===state.value.dates[0];const result=await json('/api/research/generate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({date:latest?'':date.value,force})});if(!alive)return
  if(result.date)date.value=result.date;selectedId.value=result.id||'';notice.value=result.cached?'已讀取已保存報告，未呼叫 API':'正在搜尋市場新聞並產生台指與配置報告，可切換其他頁籤。';await load()
 }catch(e){if(alive)error.value=String(e)}finally{if(alive)starting.value=false}
}
async function saveConfig(remove=false){saving.value=true;error.value=''
 try{await json('/api/research/config',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({model:model.value,api_key:remove?'':apiKey.value,remove_key:remove})});if(!alive)return;editing.value=false;notice.value=remove?'已移除本機保存金鑰；若設定環境變數仍會使用。':'API 設定已保存，尚未呼叫 API。';await load()}catch(e){if(alive)error.value=String(e)}finally{apiKey.value='';saving.value=false}
}
function history(id:string){selectedId.value=id;load()}
function download(){if(!active.value?.result)return;const content=active.value.result.parts.map(p=>p.url?'['+p.text+']('+p.url+')':p.text).join('');const u=URL.createObjectURL(new Blob([`# ${active.value.date} 收盤研究報告\n\n${content}`],{type:'text/markdown;charset=utf-8'}));const a=document.createElement('a');a.href=u;a.download=active.value.date+'-台股研究報告.md';a.click();URL.revokeObjectURL(u)}
watch(date,()=>{selectedId.value='';error.value='';load();loadPreview()})
onMounted(load);onUnmounted(()=>{alive=false;epoch++;previewEpoch++;apiKey.value='';clearTimeout(timer)})
</script>
<template>
 <section class="research-page">
  <header class="page-header"><div><div class="eyebrow">LATEST CLOSE · MARKET NEWS · RESEARCH V4</div><h1>最新收盤與新聞整理</h1><p>18:00後納入當日收盤；新報告只整理市場新聞、整體股票配置％與台指開收盤預測。</p></div><button class="research-config" @click="editing=!editing">{{editing?'收起設定':'API 設定'}}</button></header>
  <div v-if="error" class="error-banner" role="alert">{{error}}<button @click="error='';load()">重新讀取</button></div>
  <form v-if="editing||state&&!state.config.configured" class="research-settings panel" @submit.prevent="saveConfig()">
   <div><h2>連接 OpenAI API</h2><p>金鑰由本機後端保存，不會放進網頁程式或報告。{{state?.config.source}}</p></div>
   <label>API Key<input v-model="apiKey" type="password" autocomplete="new-password" placeholder="sk-…（留空沿用原金鑰）" aria-label="OpenAI API Key"></label>
   <label>模型代號<input v-model="model" aria-label="OpenAI 模型代號" required></label>
   <div class="research-actions"><button type="submit" class="primary" :disabled="saving">{{saving?'儲存中':'儲存設定'}}</button><button v-if="state?.config.configured" type="button" :disabled="saving" @click="saveConfig(true)">移除本機金鑰</button><a href="https://platform.openai.com/api-keys" target="_blank" rel="noopener noreferrer">取得 API Key ↗</a></div>
   <p>預設 chat-latest，可改為帳戶可用且支援網路搜尋的模型。產生報告只會傳送市場新聞主題、整體股票配置、台指行情與台指誤差模型，不會傳送個股或 ETF 名單；儲存設定不會呼叫 API。</p>
  </form>
  <div class="research-toolbar"><label>最新收盤交易日<select v-model="date" aria-label="研究收盤日期"><option v-if="!state?.dates.length" value="">尚無已收盤資料</option><option v-for="d in state?.dates" :key="d">{{d}}</option></select></label><span>台北時間18:00後可選當日；此前沿用最近一個完整收盤交易日</span><button class="primary" :disabled="running||!date||(!state?.config.configured&&!savedForDate)" @click="generate()"><Icon name="refresh" :size="16"/>{{running?'研究報告產生中':savedForDate?'讀取當日報告':'產生研究報告'}}</button><button v-if="savedForDate" :disabled="running||!state?.config.configured" @click="generate(true)">重新產生（再次計費）</button></div>
  <p v-if="notice" class="research-notice" role="status">{{notice}}</p>
  <div v-if="state?.running" class="research-callout">正在產生 {{state.running.date}} 的市場、配置與台指報告。完成後自動保存，切換頁籤不會重複送出。</div>
  <div class="research-layout">
   <aside class="research-history panel"><h2>研究紀錄</h2><p v-if="!state?.history.length">尚無報告。設定金鑰後，按「產生研究報告」。</p><button v-for="item in state?.history" :key="item.id" :class="{chosen:item.id===active?.id}" @click="history(item.id)"><strong>{{item.date}}</strong><span>{{item.status==='complete'?'已保存':item.status==='running'?'產生中':item.status==='interrupted'?'已中斷':'失敗'}}</span><small>{{stamp(item.created_at)}} · {{item.model}}</small></button></aside>
   <div class="research-main">
    <article v-if="active?.status==='complete'&&active.result" class="research-document panel"><header><div><span>DAILY RESEARCH</span><h2>{{active.date}} 收盤、配置與台指報告</h2><p>{{stamp(active.created_at)}} · {{active.result.model||active.model}}</p></div><button @click="download">下載 .md</button></header><div class="research-body"><template v-for="(block,i) in blocks" :key="i"><component :is="block.heading?'h3':'p'"><template v-for="(part,j) in block.parts" :key="j"><a v-if="part.url" :href="part.url" target="_blank" rel="noopener noreferrer">{{part.text}}</a><template v-else>{{part.text}}</template></template></component></template></div><footer>本機已保存 · 輸入 {{fmt(active.result.usage.input_tokens)}} / 輸出 {{fmt(active.result.usage.output_tokens)}} tokens<span v-if="active.result.request_meta"> · {{active.result.request_meta.version}} 傳送 {{fmt(active.result.request_meta.input_chars)}} 字元<template v-if="active.result.request_meta.topic_count!=null">／{{active.result.request_meta.topic_count}} 個市場主題</template><template v-else-if="active.result.request_meta.candidate_count!=null">／{{active.result.request_meta.candidate_count}} 檔舊版候選</template></span> · AI 研究供觀察，實際交易需自行判斷。</footer></article>
    <div v-else-if="active?.error" class="research-callout" role="alert">{{active.error}}。已保存的報告仍可從左側紀錄開啟。</div>
    <div v-else class="research-empty panel"><span>市場研究資料準備</span><h2>{{state?.running?'正在彙整市場新聞與台指資料':'收盤後建立單一市場版本'}}</h2><p>新報告只包含收盤摘要、最多 5 則附來源新聞、整體股票配置比例，以及下次日盤台指期開盤、收盤與四個區間點位。</p><p>個股、ETF 名單與選股回測不會送進此報告；ETF 明細請至 ETF 滾動存股規劃查看。</p></div>
    <section v-if="evidence" class="research-evidence panel"><header><h2>{{active?.status==='complete'?'本報告採用的資料快照':'待研究資料'}} · {{evidence.date}}</h2><span>新聞截至 {{stamp(evidence.news_cutoff)}} 台北</span></header><div class="research-dates"><div v-for="(value,key) in evidence.dates" :key="key"><span>{{labels[key]||key}}</span><strong>{{value||'缺少'}}</strong></div></div><div v-if="evidence.warnings.length" class="research-warnings"><p v-for="warning in evidence.warnings" :key="warning">{{warning}}</p></div><div class="research-scope"><article><span>整體股票配置</span><strong>{{allocation?.target_equity_pct==null?'待 ETF 規劃更新':fmt(allocation.target_equity_pct,1)+'%'}}</strong><p v-if="allocation">風控 {{fmt(allocation.score,1)}} · 覆蓋 {{fmt(allocation.coverage,1)}}% · {{allocation.status||'狀態待確認'}}</p><p v-else>尚無研究日以前可引用的配置快照。</p><small>配置快照 {{evidence.strategies?.date||'待更新'}}</small></article><article><span>台指預測紀錄</span><strong>{{evidence.execution?.target_date||'產生報告後保存'}}</strong><p v-if="forecast">開盤 {{fmt(forecast.open,0)}} · 收盤 {{fmt(forecast.close,0)}} · {{forecast.contract||'契約待確認'}}</p><p v-else>報告完成後保存原始預測，再以實際日盤核對。</p><small>只追蹤下一交易日日盤 08:45–13:45</small></article></div><p class="research-method">此頁不建立個股與 ETF 建議；市場新聞主題只用來限制搜尋範圍。</p></section>
    <p v-else-if="loading" class="watch-loading">讀取本機資料中…</p>
   </div>
  </div>
 </section>
</template>
<style scoped>
.research-config,.research-actions button:not(.primary),.research-toolbar>button:not(.primary){border:1px solid #d7e0d0;border-radius:7px;padding:10px 14px;font-size:.79rem;background:#fff}.research-settings{padding:24px;margin-bottom:24px;display:grid;grid-template-columns:1fr 1fr;gap:18px}.research-settings>div:first-child,.research-settings>p,.research-actions{grid-column:1/-1}.research-settings h2{font-size:1rem;margin:0}.research-settings p{font-size:.77rem;line-height:1.8;color:#7a8971;margin:7px 0 0}.research-settings label{display:flex;flex-direction:column;gap:8px;font-size:.8rem}.research-settings input,.research-toolbar select{border:1px solid #d6dfce;padding:11px;border-radius:6px;background:white;color:#435b38}.research-actions{display:flex;gap:16px;align-items:center;flex-wrap:wrap}.research-actions a{font-size:.78rem;text-decoration:underline}.research-toolbar{display:flex;align-items:center;flex-wrap:wrap;gap:14px;margin:24px 0}.research-toolbar label{display:flex;align-items:center;gap:10px;font-size:.83rem}.research-toolbar>span{font-size:.73rem;color:#87957b;flex:1}.research-toolbar>button{font-size:.8rem}.research-notice{color:#698052;font-size:.78rem}.research-callout{background:#f7f1df;color:#8d733f;padding:18px;border-radius:8px;font-size:.82rem;line-height:1.8;margin-bottom:20px}.research-layout{display:grid;grid-template-columns:205px minmax(0,1fr);gap:22px;align-items:start}.research-history{padding:20px 12px}.research-history h2{font-size:.88rem;margin:0 8px 15px}.research-history>p{font-size:.77rem;line-height:1.8;color:#87957c;padding:0 8px}.research-history button{display:flex;flex-wrap:wrap;justify-content:space-between;width:100%;padding:13px 10px;gap:6px;text-align:left;border-radius:7px;margin-top:4px}.research-history button.chosen{background:#edf3e5}.research-history strong{font-size:.83rem;font-weight:550}.research-history span{font-size:.7rem;color:#81936d}.research-history small{width:100%;font-size:.65rem;line-height:1.6;color:#96a08e;overflow-wrap:anywhere}.research-main{min-width:0}.research-empty{padding:40px;margin-bottom:22px;border-top:3px solid #799462}.research-empty>span,.research-document header span{font-size:.7rem;letter-spacing:.12em;color:#889d70}.research-empty h2{font-size:1.5rem;font-weight:500;color:#38543e}.research-empty p{font-size:.85rem;line-height:1.9;color:#829176;max-width:620px}.research-evidence{overflow:hidden}.research-evidence header{padding:22px 24px;border-bottom:1px solid #e9eee1}.research-evidence h2{font-size:.95rem;margin:0 0 9px}.research-evidence header span{font-size:.73rem;color:#94a186}.research-dates{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;padding:20px 24px}.research-dates span{display:block;font-size:.7rem;color:#94a286;margin-bottom:8px}.research-dates strong{font-size:.88rem;font-weight:500}.research-warnings{margin:0 24px 20px;padding:10px 15px;background:#fbf6e9;border-left:3px solid #c6ae77;color:#977c47}.research-warnings p{font-size:.75rem;line-height:1.6;margin:5px 0}.research-scope{display:grid;grid-template-columns:1fr 1fr;gap:14px;padding:0 24px 22px}.research-scope article{padding:18px;border:1px solid #e5ebdf;border-radius:9px;background:#fbfcf9}.research-scope span,.research-scope small{display:block;font-size:.68rem;color:#8b997f}.research-scope strong{display:block;font-size:1.25rem;margin:11px 0;color:#4b6845}.research-scope p{font-size:.75rem;line-height:1.7;color:#74856b}.research-evidence table{width:100%;border-collapse:collapse;font-size:.77rem}.research-evidence th{background:#f6f8f1;color:#8a987a;font-weight:400;white-space:nowrap}.research-evidence td,.research-evidence th{padding:14px;text-align:left;border-bottom:1px solid #ecf0e7}.research-evidence td:nth-child(3){min-width:220px;max-width:330px;line-height:1.8}.research-evidence td:nth-child(1),.research-evidence td:nth-child(4),.research-evidence td:nth-child(5){white-space:nowrap}.research-evidence small{display:block;font-size:.66rem;color:#93a083;margin-top:5px;max-width:320px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.research-method{padding:8px 24px 18px;color:#8d9a80;font-size:.72rem;line-height:1.8}.research-document{margin-bottom:24px}.research-document header{display:flex;justify-content:space-between;gap:10px;padding:32px;border-bottom:1px solid #e5eadc}.research-document h2{font-size:1.5rem;margin:12px 0;font-weight:500}.research-document header p{color:#8c997e;font-size:.76rem}.research-document header button{font-size:.74rem;color:#6b8353;align-self:start;text-decoration:underline}.research-body{padding:18px 32px 32px;color:#455b3d}.research-body h3{font-size:1.06rem;margin:28px 0 14px}.research-body p{font-size:.9rem;line-height:1.95;white-space:pre-wrap;overflow-wrap:anywhere}.research-body a{color:#6a8748;text-decoration:underline;margin:0 3px;font-size:.85em}.research-document footer{font-size:.69rem;color:#94a084;border-top:1px solid #edf0e7;padding:18px 30px;line-height:1.8}@media(max-width:1100px){.research-layout{grid-template-columns:1fr}.research-history{display:flex;overflow:auto;align-items:center;gap:8px}.research-history h2{white-space:nowrap;margin:0 10px}.research-history button{min-width:185px;width:185px}.research-history>p{margin:0}.research-dates{grid-template-columns:repeat(2,1fr)}}@media(max-width:600px){.research-settings{grid-template-columns:1fr}.research-scope{grid-template-columns:1fr}.research-empty,.research-document header{padding:24px}.research-body{padding:10px 22px 24px}.research-toolbar .primary{width:100%;justify-content:center}}
</style>
